<script>(()=>{const t=document.querySelector('[data-foot-menu-toggle]'),m=document.querySelector('[data-foot-menu]');t?.addEventListener('click',()=>m?.classList.toggle('is-open'));const s=[...document.querySelectorAll('[data-x321-slide]')];if(s.length>1){let i=0;setInterval(()=>{s[i].classList.remove('is-active');i=(i+1)%s.length;s[i].classList.add('is-active')},6500)}})();</script>
